  window.LESSONS["u2_l10"] = {"meta":{"grade":5,"subject":"과학","term":2,"unit":2,"unit_title":"날씨와 우리 생활","n":10,"covers":"10·11차시","title":"과학이 톡톡 기상 관측 장비 · 날씨와 우리 생활 마무리하기","goal":"🛰️ 여러 곳의 기상 관측 장비를 알아봐요. / 🗺️ 단원에서 배운 기상 요소·이슬·안개·구름·기압·바람을 정리해요. / ✅ 배운 내용을 스스로 평가해요.","std":"[6과06-01][6과06-02][6과06-03]","duration_min":80,"lesson_format":"관측 장비 탐색 + 단원 마무리 · 2세대 19장(7요소)","theme":"날씨 관측소","source":"2022 개정 과학 5-2 지도서 2단원(자기주도 원문 없음 — 케이티처 정본)","src_key":"u2_l10"},"slides":[{"id":"s01","stage":"도입","block":"cover","data":{"title":"땅·바다·하늘·우주에서 기상을 관측해요\n날씨와 우리 생활 단원 마무리 (2차시)","emoji":"🏁"},"suggested_extras":["v_l8_1"]},{"id":"s02","stage":"도입","block":"review","data":{"title":"지난 시간엔 무엇을 했나요?","content":"지난 시간에는 기상 요소가 잘 드러나는 **날씨 앱 화면**을 만들어 공유했어요. 오늘은 그 날씨 정보가 어디에서 오는지 알아보고 단원을 정리해요.","items":[{"q":"날씨 앱 화면 만들기 세 단계는?","a":"계획하기 → 해 보기 → 나누기"},{"q":"날씨 앱 화면에서 가장 잘 드러나야 하는 것은?","a":"기상 요소(날씨 정보)"},{"q":"댓글을 쓸 때 지킬 점은?","a":"잘한 점과 보완할 점을 바르고 고운 말로"}],"from":"u2_l08"},"suggested_extras":["q_l8_1"]},{"id":"s03","stage":"도입","block":"motivate","data":{"scene_title":"날씨 정보는 어디에서 올까?","desc":"바다 위 **부표**, 하늘의 **풍선과 드론**, 우주의 **기상 위성**이 날마다 날씨를 재고 있어요.","question":"날씨 앱의 숫자들은 **누가, 어디에서** 재는 걸까요?","img":"assets/photo/science/weather_observation_tools.jpg","tnote":{"ask":["기온은 어디에서 잴까요?","우주에서 날씨를 보는 장비는?"],"watch":"「인터넷이 알아서」로 끝내는 경우 — 재는 장비로","min":4}},"suggested_extras":["q_l8_2","r_l8_1"]},{"id":"s04","stage":"전개","block":"concept","data":{"fig":{"k":"tools","items":[{"emoji":"🗼","name":"땅","kind":"관측탑·레이더"},{"emoji":"🌊","name":"바다","kind":"관측선·부표"},{"emoji":"🎈","name":"하늘","kind":"레윈존데·드론"},{"emoji":"🛰️","name":"우주","kind":"기상 위성"}]},"title":"땅·바다·하늘·우주의 관측 장비","content":"여러 가지 기상 요소를 재고 기상 현상을 살피는 것을 **기상 관측**이라고 해요. 땅·바다·하늘·우주에서 다양한 장비로 관측해요.","tnote":{"ask":["바다에서 날씨를 재는 장비는?","기상 위성은 무엇을 보여 주나요?"],"watch":"장비 이름만 외우는 경우 — 어디에서 무엇을 재는지로","min":5}},"suggested_extras":["e_l8_1"]},{"id":"s05","stage":"전개","block":"concept","data":{"fig":{"k":"tools","items":[{"emoji":"🌡️","name":"기상 요소","kind":"기온·습도 등"},{"emoji":"🌦️","name":"생활 영향","kind":"옷차림·활동"},{"emoji":"💧","name":"이슬·안개","kind":"수증기 응결"},{"emoji":"🧭","name":"기압과 바람","kind":"고 → 저"}]},"title":"기상 요소와 우리 생활","content":"단원에서 배운 네 가지 학습 요소를 **한눈에** 정리해요.","tnote":{"ask":["네 줄 가운데 가장 자신 있는 것은?","서로 이어지는 줄은 어느 것인가요?"],"watch":"용어만 쓰고 뜻을 빠뜨리는 경우","min":5}},"suggested_extras":["t_l8_1"]},{"id":"s06","stage":"전개","block":"concept","data":{"fig":{"k":"bins","bins":[{"name":"수증기의 응결","emoji":"💧","tone":"t0","items":[{"emoji":"🌿","name":"이슬 — 표면"},{"emoji":"🌫️","name":"안개 — 땅 가까이"},{"emoji":"☁️","name":"구름 — 높은 곳"}],"hint":"생기는 위치가 달라요"},{"name":"기압과 날씨","emoji":"⚖️","tone":"t1","items":[{"emoji":"☀️","name":"고기압 — 맑음"},{"emoji":"🌧️","name":"저기압 — 흐림·비"}],"hint":"위성 사진의 구름"}]},"title":"이슬·안개·구름 · 고기압과 저기압","content":"이슬·안개·구름은 **위치**로, 고기압·저기압은 **날씨 특징**으로 견줘요.","tnote":{"ask":["안개와 구름을 무엇으로 구분하나요?","저기압일 때 위성 사진은?"],"watch":"「항상」으로 단정하는 경우 — 대체로","min":4}},"suggested_extras":["e_l8_2","t_l8_2"]},{"id":"s07","stage":"전개","block":"concept","data":{"fig":{"k":"bins","bins":[{"name":"낮","emoji":"☀️","tone":"t0","items":[{"emoji":"🏝️","name":"육지 위 저기압"},{"emoji":"🌊","name":"바다 위 고기압"}],"hint":"해풍: 바다 → 육지"},{"name":"밤","emoji":"🌙","tone":"t1","items":[{"emoji":"🏝️","name":"육지 위 고기압"},{"emoji":"🌊","name":"바다 위 저기압"}],"hint":"육풍: 육지 → 바다"}]},"title":"바닷가의 바람 정리","content":"바람은 두 지역 사이에 **기압 차이**가 생겨 **고기압에서 저기압으로** 공기가 이동하는 거예요.","tnote":{"ask":["낮에 온도가 높은 곳은?","밤에 기압이 높은 곳은?"],"watch":"낮과 밤을 바꾸어 쓰는 경우","min":4}},"suggested_extras":["q_l8_3"]},{"id":"s08","stage":"전개","block":"misconception","data":{"title":"이런 생각, 맞을까요?","label":"자주 하는 생각","wrong":"날씨 예보는 관측 장비 자료만 있으면 저절로 정확해진다","right":"관측 자료는 **기상 전문가**가 분석하고 실제 상황을 **종합적으로 판단**해야 예보가 돼요. 또 우리나라 자료뿐 아니라 **전 세계의 관측 자료**를 함께 모아요.","hint":"일기 예보관과 기상 연구원이 하는 일을 소개하며 「사람의 판단」이 왜 필요한지 묻게 하세요.","tnote":{"ask":["예보관은 무엇을 하나요?","다른 나라 자료는 왜 필요할까요?"],"watch":"「기계가 다 한다」로 끝내는 경우","min":3}},"suggested_extras":["x_l8_1","x_l8_2"]},{"id":"s09","stage":"기본문제","block":"basic_problem","data":{"title":"기본 문제 ①","scenario":{"icon":"🗺️","body":"배운 내용을 확인해요."},"question":"날씨를 표현하는 기상 요소가 아닌 것은 무엇일까요?","options":[{"text":"하늘의 색깔","correct":true},{"text":"기온"},{"text":"습도"},{"text":"강수량"}],"note":"풀이: 기상 요소에는 기온, 바람, 습도, 구름의 양, 강수량 등이 있어요. → **하늘의 색깔**"},"suggested_extras":["t_l8_3"]},{"id":"s10","stage":"기본문제","block":"basic_problem","data":{"title":"기본 문제 ②","scenario":{"icon":"💬","body":"날씨와 우리 생활에 관한 친구들의 말을 들었어요."},"question":"옳게 말한 것을 모두 고르세요.","options":[{"text":"이슬·안개·구름은 수증기가 응결해 생겨","correct":true},{"text":"고기압 지역은 저기압 지역보다 대체로 맑아","correct":true},{"text":"바람은 고기압에서 저기압으로 불어","correct":true},{"text":"구름은 지표면 가까이에 떠 있어"}],"multi":true,"note":"풀이: 지표면 가까이에 떠 있는 것은 안개예요. → 알맞은 것 **3개**"},"suggested_extras":["e_l8_3"]},{"id":"s11","stage":"기본문제","block":"basic_problem","data":{"title":"기본 문제 ③","scenario":{"icon":"🛰️","body":"기상 관측 장비를 알아봐요."},"question":"우주에서 지구의 구름 모습을 찍어 날씨를 관측하는 장비는 무엇일까요?","options":[{"text":"기상 위성","correct":true},{"text":"해양 기상 부표"},{"text":"측우기"},{"text":"종합 기상 관측탑"}],"note":"풀이: 기상 위성은 우주에서 구름의 모습을 관측해요. → **기상 위성**"},"suggested_extras":["q_l8_4"]},{"id":"s12","stage":"기본문제","block":"leveled_problem","data":{"title":"수준을 골라 풀어요","levels":{"기본":{"q":"밤에 바닷가에서 육지에서 바다로 부는 바람은?","a":"육풍","steps":["밤에 육지가 빨리 식는다","육지 위가 고기압이 된다","육지 → 바다, 육풍이라고 답한다"]},"도전":{"q":"일상생활에서 기상 요소를 재는 방법을 두 가지 말해 봐요.","a":"여러 답 (예: 온도계로 기온 · 빗물을 받아 강수량 · 바람개비로 바람)","steps":["기상 요소 다섯 가지를 떠올린다","집이나 학교에 있는 도구를 찾는다","두 가지를 짝지어 말한다"]},"심화":{"q":"내일 기상 요소 세 가지 이상을 골라 일기 예보를 쓰고, 그 날씨에 맞는 생활 안내를 붙여 봐요.","a":"여러 답 (예: 기온 15 °C, 습도 80 %, 구름 많음 — 비가 올 수 있으니 우산을 챙기세요)","open":true}},"tnote":{"ask":["기본에서 밤의 기압을 바르게 썼나요?","도전에서 도구와 기상 요소를 짝지었나요?"],"watch":"심화에서 생활 안내가 빠진 경우","min":5}},"suggested_extras":["q_l8_5","g_l8_1"]},{"id":"s13","stage":"응용문제","block":"offline_activity","data":{"title":"단원 정리판 · 날씨 낱말 찾기 놀이","type":"group","goal":"모둠별로 기상 관측 장비 카드를 장소별로 나누고, 붙임딱지로 단원 정리판 네 줄(기상 요소·생활 / 이슬·안개·구름 / 고·저기압 날씨 / 바람)을 완성한 뒤 날씨 낱말 찾기 놀이와 문제로 스스로 평가하기","steps":["관측 장비를 땅·바다·하늘·우주로 나누어 붙인다","붙임딱지로 단원 정리판 네 줄을 채운다","옳은 설명의 글자를 모아 날씨 낱말을 완성하는 놀이를 한다","실험관찰 34~35쪽 문제를 풀고 성취기준 셋을 스스로 평가한다"],"solo":["관측 장비 넷을 장소와 짝지어 쓴다","정리판 네 줄을 공책에 채우고 스스로 평가한다"],"materials":["붙임딱지(과학 119쪽)","실험관찰 34~35쪽","정리판 활동지","색연필"],"minutes":30,"tnote":{"ask":["정리판마다 뜻까지 썼나요?","스스로 평가에서 가장 자신 없는 것은?"],"watch":"정답 맞히기에만 몰두해 정리판을 건너뛰는 경우","min":30}},"suggested_extras":["g_l8_2","t_l8_4"]},{"id":"s14","stage":"응용문제","block":"real_world","data":{"title":"국가기상슈퍼컴퓨터와 예보관","scenario":{"icon":"🖥️","body":"기상청은 땅·바다·하늘·우주에서 모은 관측 자료를 **슈퍼컴퓨터**로 분석해요. 그리고 **일기 예보관**이 자료와 실제 상황을 종합해 예보와 주의보를 발표해요. 최근에는 **인공지능**을 예보에 쓰려는 연구도 하고 있어요."},"content":"관측 → 분석 → 판단이 이어져야 **정확한 예보**가 돼요."},"suggested_extras":["r_l8_2","r_l8_3"]},{"id":"s15","stage":"응용문제","block":"advanced_problem","data":{"title":"생각을 넓혀요","context":"맑은 날 바닷가로 체험 학습을 가요. 오후에는 바다에서 연을 날리고, 저녁에는 해변에서 캠프파이어를 해요.","challenge":"연을 날릴 때와 캠프파이어 연기가 흘러갈 방향을 바람과 기압으로 예상해 봐요.","note":"풀이: **낮**에는 육지가 더 따뜻해 저기압이 되므로 바다에서 육지로 **해풍**이 불어 연은 **육지 쪽**으로 날아가요. **저녁·밤**에는 육지가 빨리 식어 고기압이 되므로 육지에서 바다로 **육풍**이 불어 연기는 **바다 쪽**으로 흘러가요.","tnote":{"ask":["낮에 기압이 높은 곳은?","밤에는 어떻게 바뀌나요?"],"watch":"낮과 밤을 같은 방향으로 쓰는 경우","min":4}},"suggested_extras":["t_l8_5"]},{"id":"s16","stage":"정리","block":"exit_ticket","data":{"title":"오늘 확인해요","items":[{"q":"기상 관측이란 무엇인가요?","a":"여러 가지 기상 요소를 재고 기상 현상을 살피는 것"},{"q":"이슬·안개·구름의 공통점은?","a":"공기 중의 수증기가 응결해 나타나요"},{"q":"바람은 어느 쪽으로 부나요?","a":"고기압에서 저기압으로"}],"self":["오늘 배운 것을 혼자 설명할 수 있어요","조금 헷갈려요","다시 배우고 싶어요"]},"suggested_extras":[]},{"id":"s17","stage":"정리","block":"summary","data":{"title":"오늘 배운 것","points":["날씨는 **기상 요소**로 나타내고, 우리 **생활에 영향**을 줘요. 이슬·안개·구름은 **수증기의 응결**로 생겨요.","고기압은 대체로 **맑고** 저기압은 대체로 **흐려요**. 바람은 **고기압에서 저기압으로** 불어요.","부표·풍선·위성이 잰 숫자가 모여 내일 우산을 챙길지 알려 줘요."],"arrows":["기상 요소 — 날씨와 생활","이슬·안개·구름 — 수증기 응결","고·저기압의 날씨 — 바람은 고 → 저"]},"suggested_extras":["r_l8_1"]},{"id":"s18","stage":"정리","block":"self_assessment","data":{"title":"스스로 점검해요","items":["📚 지식·이해 — 기상 요소·이슬·안개·구름·기압·바람을 설명할 수 있나요?","🔧 과정·기능 — 배운 내용을 정리판과 문제로 스스로 확인할 수 있나요?","💛 가치·태도 — 날씨와 우리 생활의 관계에 흥미가 생겼나요?"],"prompts":["「날씨와 우리 생활」을 공부하고 새로 알게 된 것을 한 문장으로 써 봐요."]},"suggested_extras":["e_l8_3"]},{"id":"s19","stage":"정리","block":"next_lesson","data":{"title":"이 단원을 마쳐요","preview":"날씨와 우리 생활 단원을 마쳤어요. 다음 단원 「열과 우리 생활」에서 온도와 열의 이동을 알아봐요.","emoji":"🔥"},"suggested_extras":["c_l8_1"]}],"extras":[{"id":"v_l8_1","type":"video","icon":"🎥","title":"기상 관측 장비 영상","url":"https://www.youtube.com/results?search_query=%EA%B8%B0%EC%83%81%EC%B2%AD+%EA%B8%B0%EC%83%81+%EA%B4%80%EC%B8%A1+%EC%9E%A5%EB%B9%84+%EB%A0%88%EC%9C%88%EC%A1%B4%EB%8D%B0+%EA%B8%B0%EC%83%81+%EC%9C%84%EC%84%B1","description":"땅·바다·하늘·우주의 관측 장비를 소개하는 장면.","source":"유튜브 검색 (교사 사전 확인 권장)","fit_slides":["concept","motivate"]},{"id":"q_l8_1","type":"fun_question","icon":"💡","title":"숫자의 출처","content":"날씨 앱 숫자는 어디에서 왔을까요?","fit_slides":["concept","basic_problem"]},{"id":"q_l8_2","type":"fun_question","icon":"💡","title":"레윈존데","content":"풍선에 단 관측 장비는 무엇을 잴까요?","fit_slides":["concept","basic_problem"]},{"id":"q_l8_3","type":"fun_question","icon":"💡","title":"세계 자료","content":"다른 나라 관측 자료는 왜 필요할까요?","fit_slides":["concept","basic_problem"]},{"id":"q_l8_4","type":"fun_question","icon":"💡","title":"우리 학교 관측소","content":"우리 학교에서 기온을 재려면?","fit_slides":["concept","basic_problem"]},{"id":"q_l8_5","type":"fun_question","icon":"💡","title":"AI 예보","content":"인공지능은 예보를 어떻게 도울까요?","fit_slides":["concept","basic_problem"]},{"id":"t_l8_1","type":"tip","icon":"🧩","title":"스스로 먼저","content":"학생이 먼저 정리판을 채우고 수업을 이어 가요(지도서).","fit_slides":["concept","misconception"]},{"id":"t_l8_2","type":"tip","icon":"🧩","title":"네 학습 요소","content":"기상 요소 · 날씨와 생활 · 이슬·안개·구름 · 고기압과 저기압으로 묶어요.","fit_slides":["concept","misconception"]},{"id":"t_l8_3","type":"tip","icon":"🧩","title":"진로 이야기","content":"기상 연구원·일기 예보관을 소개해요.","fit_slides":["concept","misconception"]},{"id":"t_l8_4","type":"tip","icon":"🧩","title":"평가 자료","content":"학업 성취도·서술형·심화 평가를 함께 써요.","fit_slides":["concept","misconception"]},{"id":"t_l8_5","type":"tip","icon":"🧩","title":"다음 단원","content":"다음 단원 준비물을 미리 안내해요.","fit_slides":["concept","misconception"]},{"id":"r_l8_1","type":"real_world","icon":"🌍","title":"슈퍼컴퓨터","content":"기상청 슈퍼컴퓨터가 관측 자료를 분석해요.","fit_slides":["real_world","summary"]},{"id":"r_l8_2","type":"real_world","icon":"🌍","title":"기상박물관","content":"우리나라 기상 과학의 역사를 볼 수 있어요.","fit_slides":["real_world","summary"]},{"id":"r_l8_3","type":"real_world","icon":"🌍","title":"해양 부표","content":"바다 위에서 파도와 바람을 재요.","fit_slides":["real_world","summary"]},{"id":"g_l8_1","type":"game","icon":"🎮","title":"낱말 찾기","content":"옳은 설명의 글자를 모아 날씨 낱말을 만들어요.","fit_slides":["leveled_problem","offline_activity"]},{"id":"g_l8_2","type":"game","icon":"🎮","title":"장비 짝짓기","content":"관측 장비와 장소 카드를 짝지어요.","fit_slides":["leveled_problem","offline_activity"]},{"id":"x_l8_1","type":"misconception","icon":"⚠️","title":"기계가 다","content":"예보는 기계가 다 한다고 여기는 실수.","fit_slides":["misconception","basic_problem"]},{"id":"x_l8_2","type":"misconception","icon":"⚠️","title":"안개=구름","content":"안개와 구름을 같은 곳에 생긴다고 여기는 실수.","fit_slides":["misconception","basic_problem"]},{"id":"e_l8_1","type":"example","icon":"📝","title":"단원 정리판","content":"네 줄 정리판을 붙입니다.","fit_slides":["concept","offline_activity"]},{"id":"e_l8_2","type":"example","icon":"📝","title":"관측 장비 지도","content":"땅·바다·하늘·우주 장비 그림을 붙입니다.","fit_slides":["concept","offline_activity"]},{"id":"e_l8_3","type":"example","icon":"📝","title":"성취기준 셋","content":"스스로 평가 세 칸을 붙입니다.","fit_slides":["concept","offline_activity"]},{"id":"c_l8_1","type":"checklist","icon":"✅","title":"다음 단원 준비","content":"단원 평가지 · 다음 단원 교과서.","fit_slides":["next_lesson"]}]};
